    for potential_factor in factors:
        is_prime = True
        for j in range(2,int(math.sqrt(potential_factor))+1):
            if potential_factor % j == 0 and potential_factor != j:
                is_prime = False
        if is_prime:
            prime_factors.append(potential_factor)

# Return the largest prime factor

